import { CSS, focusRing } from "../../../stitches.config";
import { Box, Flex, Text } from "../../atoms";
import { AvatarComponent, AvatarImage } from "../../atoms/Avatar/Avatar";
import { Skeleton } from "../../atoms/Skeleton/Skeleton";
import { CopyButton } from "../../atoms/TextField/TextField";
import { Link } from "../../atoms/Link/Link";
import { ExternalLinkIcon } from "../../icons";

// Link and copy icons share one size, colour and hover so neither reads as
// heavier than the other next to the name.
const ICON_SIZE = "18px";


type AvatarProps = {
  src: string;
  credential?: string;
  isLoading?: boolean;
};

const Avatar = (props: AvatarProps) => {
  let credentialColor;

  switch (props.credential) {
    case "gold":
      credentialColor = "$gradientGold";
      break;
    case "silver":
      credentialColor = "$gradientSilver";
      break;
    case "bronze":
      credentialColor = "$gradientBronze";
      break;
    case "base":
      credentialColor = "$obolGreen";
      break;
    default:
      credentialColor = "transparent";
  }
  return (
    <Box
      css={{
        position: "relative",
        "@sm": { width: "44px", height: "44px" },
        "@bp2": { width: "88px", height: "88px" },
        borderRadius: "50%",
        background: props.isLoading ? "transparent" : credentialColor,
        backgroundBlendMode: "multiply",
      }}
    >
      <Box
        css={{
          position: "absolute",
          left: 0,
          right: 0,
          top: 0,
          bottom: 0,
          margin: "auto",
          backgroundColor: "$bg01",
          "@sm": { width: "$2xl", height: "$2xl" },
          "@bp2": { width: "$5xl", height: "$5xl" },

          borderRadius: "50%",
        }}
      >
        {props.isLoading ? (
          <Skeleton variant="circle" />
        ) : (
          <AvatarComponent>
            <AvatarImage
              css={{
                position: "absolute",
                left: 0,
                right: 0,
                top: 0,
                bottom: 0,
                margin: "auto",
                borderRadius: "50%",
                objectFit: "contain",
                "@sm": { width: "36px", height: "36px" },
                "@bp2": { width: "72px", height: "72px" },
              }}
              src={props.src}
              // Decorative: the profile name is right next to it.
              alt=""
            />
          </AvatarComponent>
        )}
      </Box>
    </Box>
  );
};

type DateInfoProps = {
  css?: CSS;
  date: Date;
};

const DateInfo = (props: DateInfoProps) => {
  return (
    <Flex
      css={{
        width: "max-content",
        "@sm": { flexDirection: "row", mt: "$xxs", ml: "$xxs" },
        "@bp2": { flexDirection: "column", ml: "$sm" },
        gap: "$xxs",
        ...props.css,
      }}
    >
      <Text
        size="3"
        color="muted"
        css={{ fontStyle: "italic", fontWeight: "$medium" }}
      >
        Since
      </Text>
      <Text
        color="textLight"
        css={{
          "@sm": { fontWeight: "$normal", fontSize: "$4" },
          "@bp2": { fontWeight: "$medium", fontSize: "$5" },
        }}
      >
        {props.date.toLocaleDateString("en-GB", {
          month: "short",
          year: "numeric",
        })}
      </Text>
    </Flex>
  );
};

type EnsNameProps = {
  css?: CSS;
  name: string;
  address?: string;
  url?: string;
  isLoading?: boolean;
};

const EnsName = (props: EnsNameProps) => {
  const etherscanUrl = props.url || `https://etherscan.io/address/${props.address}`;

  return (
    <Flex
      css={{
        alignItems: "center",
        gap: "$xxs",
        "@sm": { ml: "$xxs" },
        "@bp2": { mt: "$xxxs" },
        ...props.css,
      }}
    >

      {props.isLoading ? (
        <Skeleton variant="title" />
      ) : props.address && props.name ? (
        <>
          <Link
            target="_blank"
            rel="noopener noreferrer"
            href={etherscanUrl}
            css={{
              ...focusRing,
              height: "auto",
              gap: "$xxs",
              borderRadius: "$1",
              color: "$textLight",
              "& svg": { width: ICON_SIZE, height: ICON_SIZE, flexShrink: 0 },
              "& svg path": { fill: "none", stroke: "currentColor" },
              "&:hover": { color: "$obolGreen" },
              "&:hover svg path": { fill: "none", stroke: "currentColor" },
            }}
          >
            <Text
              variant="h4"
              css={{
                color: "inherit",
                lineHeight: 1,
                "@sm": { fontWeight: "$semibold" },
                "@bp2": { fontWeight: "$bold" },
              }}
            >
              {props.name}
            </Text>
            <ExternalLinkIcon />
          </Link>
          <CopyButton
            value={props.address}
            ghost
            css={{
              p: 0,
              border: "none",
              borderRadius: "$1",
              color: "$textLight",
              "& svg": { width: ICON_SIZE, height: ICON_SIZE },
              "&:hover": { color: "$obolGreen" },
            }}
          />
        </>
      ) : null}
    </Flex>
  );
};

export type ProfileProps = {
  src?: string;
  name: string;
  address?: string;
  url?: string;
  date?: Date;
  credential?: string;
  css?: CSS;
  isLoading?: boolean;
};

export const Profile = (props: ProfileProps) => {
  return (
    <Flex
      css={{
        maxWidth: "300px",
        height: "max-content",
        flexDirection: "column",
      }}
    >
      <Flex
        css={{
          width: "max-content",
          alignItems: "center",
          "@bp2": { alignItems: "flex-end" },
        }}
      >
        <Avatar
          src={props.src || "/assets/profile-default.png"}
          credential={props.credential}
          isLoading={props.isLoading}
        />
        <EnsName
          name={props.name}
          address={props.address}
          url={props.url}
          isLoading={props.isLoading}
          css={{ "@bp2": { display: "none" } }}
        />
        {props.date && (
          <DateInfo css={{ "@sm": { display: "none" } }} date={props.date} />
        )}
      </Flex>

      <EnsName
        name={props.name}
        address={props.address}
        url={props.url}
        isLoading={props.isLoading}
        css={{ "@sm": { display: "none" } }}
      />
      {props.date && (
        <DateInfo css={{ "@bp2": { display: "none" } }} date={props.date} />
      )}
    </Flex>
  );
};
